-- «Winback · un año sin costo»: la cadencia para los clientes que se fueron.
--
-- Sustituye por completo a «Winback · los que se fueron» (15 correos simples en
-- 135 días, con el año sin costo escondido hasta el correo 10). La instrucción
-- del dueño (13-sep-2026) es la contraria: el eje de TODA la campaña es un año
-- completo de Sacs sin costo, ofrecido desde el primer correo a través de una
-- reunión con el director general, Aarón Herzberg («Reunión director general»,
-- /agendar/director-general, ver migration-winback-reunion-director-general.sql).
--
-- 10 correos en layout lienzo con portada (gpt-image-2) + 5 WhatsApp con foto
-- (plantillas anosincosto_* creadas en Meta el 13-sep, categoría MARKETING, con
-- encabezado IMAGE y botón URL a la agenda). 32 días en total: la oferta ya está
-- en la mesa desde el día 1, así que no hay por qué estirarla cuatro meses.
--
--   día  1  correo  Un año sin costo, dicho por el director
--   día  2  wa      anosincosto_director
--   día  3  correo  Qué pasa en esos 30 minutos
--   día  6  correo  La razón por la que te fuiste ya no existe   (servicio)
--   día  7  wa      anosincosto_servicio
--   día  9  correo  Más de mil mejoras en seis meses
--   día 12  correo  Implementado en siete días
--   día 14  wa      anosincosto_siete_dias
--   día 16  correo  El año, en letra grande                      (términos)
--   día 20  correo  Así se atiende hoy una cuenta                (servicio)
--   día 22  wa      anosincosto_agenda
--   día 24  correo  Vuelves donde lo dejaste
--   día 28  correo  Las siete preguntas
--   día 30  wa      anosincosto_puerta
--   día 32  correo  La puerta queda abierta
--
-- Además: 14 contactos de empresas con suscripción cancelada y ninguna activa
-- seguían como lifecycle 'cliente' (nunca se marcaron al cancelar). Se mueven a
-- churned/descartado con estatus_lead_at = ahora para que entren por la puerta
-- de la secuencia (ancla estatus_lead_at, corte 180 días). Con eso salen de
-- «Crecimiento», que es para clientes activos.
--
-- La secuencia queda APAGADA: se prende cuando el dueño lo diga y las 5
-- plantillas de WhatsApp estén APPROVED en Meta.
begin;

-- 1) Fuera los 20 pasos y los 15 correos viejos (0 envíos registrados).
delete from crm_secuencia_pasos where secuencia_id = '11111111-2222-4333-8444-5555555555c1';
delete from email_templates where nombre like 'Winback %';

-- 2) Los 10 correos nuevos.
insert into email_templates (nombre, asunto, preview_text, tipo, layout, categoria, bloques, activo)
values ('Año sin costo 1 · Un año sin costo, dicho por el director', '{{nombre|Hola}}, un año de Sacs sin costo — y una reunión con Aarón Herzberg', 'No es un descuento ni una prueba: doce meses del plan completo, implementado por nosotros en 7 días.', 'automatizado', 'lienzo', 'relacion', '[{"tipo":"portada","imagen":"https://www.sacscloud.com/email/portadas/wb-director.jpg","alt":"","etiqueta":"De parte de la dirección de Sacs","titulo":"Un año de Sacs sin costo, y quien te lo dice es el director","id":"po0"},{"id":"te1","tipo":"texto","texto":"Hola {{nombre|Hola}}, te escribe Andrea, de Sacs.\n\nHace un tiempo {{empresa|tu negocio}} usaba Sacs y dejó de usarlo. No te voy a hacer la pregunta de siempre —«¿qué pasó?»— como si no supiéramos nada. Sí sabemos: cuando un cliente se va, casi nunca es por el sistema. Es por cómo lo acompañamos. Y de eso quiero hablarte hoy, con una propuesta concreta y con nombre."},{"id":"en2","tipo":"encabezado","nivel":2,"texto":"La propuesta, sin rodeos"},{"id":"te3","tipo":"texto","texto":"**Un año completo de Sacs sin costo.** No un mes de prueba ni un descuento: doce meses del plan más completo que tenemos, con todos los módulos, implementado por nuestro equipo en siete días y con una persona asignada a tu cuenta desde el primero."},{"id":"me4","tipo":"metricas","items":[{"cifra":"12 meses","texto":"del plan completo, sin costo"},{"cifra":"7 días","texto":"para dejarlo operando"},{"cifra":"+1,000","texto":"mejoras en los últimos 6 meses"}]},{"id":"en5","tipo":"encabezado","nivel":2,"texto":"Por qué te lo dice el director"},{"id":"te6","tipo":"texto","texto":"Porque una oferta así no la puede hacer un vendedor. **Aarón Herzberg, director general de Sacs**, abrió un espacio en su agenda para recibir personalmente a los clientes que se fueron. Treinta minutos por videollamada, con tres cosas en la mesa: escuchar qué pasó, enseñarte lo que cambió desde entonces y, si tiene sentido para tu negocio, dejarte el año activado en esa misma llamada."},{"id":"ci7","tipo":"cita","texto":"Si un cliente se fue, algo hicimos mal. Prefiero escucharlo yo y arreglarlo con hechos, no mandar otra promoción.","autor":"Aarón Herzberg, director general de Sacs"},{"id":"bo8","tipo":"boton","texto":"📅 Reservar mi reunión con Aarón","href":"https://www.sacscloud.com/agendar/director-general","align":"center","sub":"30 minutos por videollamada · eliges día y hora · sin costo y sin compromiso"},{"id":"av9","tipo":"aviso","texto":"No hay que preparar nada ni traer a nadie. Eliges el día y la hora, te llega la liga de la videollamada y un recordatorio antes. Si prefieres que te llame yo primero, contéstame este correo o escríbeme por WhatsApp."},{"id":"bo10","tipo":"boton","texto":"💬 O escríbeme por WhatsApp","href":"https://wa.me/525593027234?text=Hola%20Andrea%2C%20me%20interesa%20la%20reuni%C3%B3n%20con%20Aar%C3%B3n%20por%20el%20a%C3%B1o%20sin%20costo.%20%C2%BFMe%20llamas%3F","align":"center","sub":"Te llamo yo y lo agendamos juntos","color":"#2AB5A0"},{"id":"te11","tipo":"texto","texto":"En los próximos días te voy a contar con detalle qué cambió: el servicio, las mejoras del sistema y cómo se implementa en una semana. Pero la reunión ya está abierta desde hoy."}]'::jsonb, true);

insert into email_templates (nombre, asunto, preview_text, tipo, layout, categoria, bloques, activo)
values ('Año sin costo 2 · Qué pasa en esos 30 minutos', 'Qué pasa en la reunión con Aarón, minuto a minuto', 'Sin presentación de ventas: tres bloques y una decisión que se toma con calma.', 'automatizado', 'lienzo', 'relacion', '[{"tipo":"portada","imagen":"https://www.sacscloud.com/email/portadas/wb-reunion.jpg","alt":"","etiqueta":"La reunión","titulo":"Treinta minutos con el director, minuto a minuto","id":"po0"},{"id":"te1","tipo":"texto","texto":"Hola {{nombre|Hola}}. Sé que «reunión con el director» suena a algo formal o, peor, a una junta de ventas con otro nombre. No es ninguna de las dos. Te cuento exactamente cómo va, para que decidas con la información completa."},{"id":"en2","tipo":"encabezado","nivel":2,"texto":"Los tres bloques"},{"id":"li3","tipo":"lista","items":["**Minutos 1 a 10 · Escuchar.** Aarón te pregunta qué pasó y se calla. Qué te prometieron, qué no llegó, en qué momento dejaste de entrar. Todo lo que digas se anota y se vuelve una tarea con responsable: es la única forma de que un cliente que se fue nos sirva para no perder al siguiente.","**Minutos 10 a 20 · Enseñar.** Te muestra en pantalla —en una cuenta real, no en diapositivas— lo que cambió en los últimos seis meses: el asistente de IA, la nivelación de inventario entre tiendas, el punto de venta móvil, la venta por TikTok Shop, los reportes que salen solos. Solo lo que aplica a {{empresa|tu negocio}}.","**Minutos 20 a 30 · Decidir.** Si quieres el año sin costo, se activa ahí mismo y se agenda el arranque de siete días con tu consultora asignada. Si no, te vas con una idea clara de qué hay y sin ningún compromiso. Las dos salidas son buenas."]},{"id":"en4","tipo":"encabezado","nivel":2,"texto":"Lo que no pasa"},{"id":"li5","tipo":"lista","items":["No hay presentación corporativa ni «déjame contarte quiénes somos».","No se te pide tarjeta, firma ni anticipo: el año no tiene costo, y lo dice el director en persona.","No te vamos a llamar tres veces después. Si dices que no, se respeta."]},{"id":"te6","tipo":"texto","texto":"Después de la reunión te llega una **minuta por correo** con lo que se habló y los compromisos de cada lado, con fecha. Así trabajamos ahora con todos: lo que se dice, se escribe."},{"id":"bo7","tipo":"boton","texto":"📅 Reservar mi reunión con Aarón","href":"https://www.sacscloud.com/agendar/director-general","align":"center","sub":"Videollamada de 30 minutos · con recordatorio un día antes y tres horas antes"},{"id":"te8","tipo":"texto","texto":"Si por agenda te queda mejor una hora fuera del calendario, contéstame este correo y lo acomodamos."}]'::jsonb, true);

insert into email_templates (nombre, asunto, preview_text, tipo, layout, categoria, bloques, activo)
values ('Año sin costo 3 · La razón por la que te fuiste ya no existe', '{{nombre|Hola}}, la razón por la que te fuiste ya no existe', 'Se entraba solo, nadie avisaba y pedir algo tardaba. Las tres se cambiaron, y así se ve hoy.', 'automatizado', 'lienzo', 'relacion', '[{"tipo":"portada","imagen":"https://www.sacscloud.com/email/portadas/wb-servicio.jpg","alt":"","etiqueta":"El servicio","titulo":"Fuimos a preguntar por qué se van los clientes. Esto encontramos.","id":"po0"},{"id":"te1","tipo":"texto","texto":"Hola {{nombre|Hola}}. A finales del año pasado hicimos algo que debimos hacer mucho antes: hablar con los clientes que se habían ido y preguntarles, sin defendernos. Contestaron más de los que esperábamos. Y casi nadie dijo «el sistema no sirve». Dijeron otra cosa, y dolió más."},{"id":"en2","tipo":"encabezado","nivel":2,"texto":"Las tres razones que se repitieron"},{"id":"li3","tipo":"lista","items":["**«Nos dejaron solos al arrancar.»** Se entregaba el acceso y un video, y se daba por hecho que cada quien encontraría el camino. Quien tenía tiempo lo encontraba; quien no, se quedaba a la mitad y dejaba de entrar.","**«Nadie se dio cuenta de que dejamos de usarlo.»** Un cliente podía pasar meses sin entrar y no recibir ni una llamada. Nos enterábamos cuando cancelaba.","**«Pedir algo tardaba.»** Un ajuste, una regla, un reporte: entraba a una bandeja de soporte donde el caso era un número, y la respuesta llegaba cuando llegaba."]},{"id":"en4","tipo":"encabezado","nivel":2,"texto":"Qué se cambió, una por una"},{"id":"li5","tipo":"lista","items":["**Una consultora con nombre desde el día uno.** Cada cuenta tiene una persona asignada que arranca contigo, te acompaña las primeras semanas y sigue siendo tu contacto después. No una bandeja: una persona que sabe cómo se llama tu tienda.","**Plan de arranque por escrito y punto de «listo» acordado.** Antes de tocar el sistema se escribe qué se carga, quién lo hace y qué día queda operando. Cuando se cumple, lo firmamos los dos.","**El sistema avisa cuando dejas de entrar.** Si una cuenta baja su actividad, se detecta en días —no en meses— y alguien del equipo te llama para ver qué está pasando, antes de que se vuelva una cancelación.","**Minuta después de cada sesión y cada llamada.** Lo que se acordó, con responsable y fecha, te llega por correo. Los compromisos con fecha se persiguen solos.","**Atención por WhatsApp con equipo detrás.** Un número oficial —+52 55 9302 7234— donde contesta gente, con horario claro y respuesta en el día. Y Axo, el asistente de IA dentro del sistema, resuelve al momento lo que antes era un ticket: configurar una regla, sacar un reporte, corregir un dato.","**La dirección accesible.** Si algo no avanza, se escala a dirección y responde. La reunión con Aarón es exactamente eso, abierta desde el primer correo."]},{"id":"ci6","tipo":"cita","texto":"El producto se arregla con código. El servicio se arregla con personas que se hacen responsables. Nos faltaba lo segundo.","autor":"Aarón Herzberg, director general de Sacs"},{"id":"av7","tipo":"aviso","texto":"Si tu razón fue alguna de las tres, era culpa nuestra y ya no pasa. Si fue otra, es justo lo que Aarón quiere oír en la reunión."},{"id":"bo8","tipo":"boton","texto":"📅 Reservar mi reunión con Aarón","href":"https://www.sacscloud.com/agendar/director-general","align":"center","sub":"Cuéntaselo a quien puede cambiarlo · 30 minutos, sin costo"},{"id":"te9","tipo":"texto","texto":"En el siguiente correo te platico lo que cambió en el sistema, que es mucho. Pero quería que esto fuera primero, porque fue lo primero que falló."}]'::jsonb, true);

insert into email_templates (nombre, asunto, preview_text, tipo, layout, categoria, bloques, activo)
values ('Año sin costo 4 · Más de mil mejoras en seis meses', 'Más de 1,000 mejoras en seis meses: lo que Sacs hace hoy y antes no', 'Asistente de IA, nivelación entre tiendas, TikTok Shop, punto de venta móvil, bancos. Por área.', 'automatizado', 'lienzo', 'relacion', '[{"tipo":"portada","imagen":"https://www.sacscloud.com/email/portadas/wb-mejoras.jpg","alt":"","etiqueta":"El sistema","titulo":"Más de mil mejoras en seis meses. Estas son las que se notan.","id":"po0"},{"id":"te1","tipo":"texto","texto":"Hola {{nombre|Hola}}. En los últimos seis meses el equipo de producto publicó **más de mil mejoras** al sistema: correcciones, funciones nuevas y módulos completos. No te las voy a listar todas. Te dejo las que cambian el día a día de un negocio como {{empresa|el tuyo}}, agrupadas por área, para que veas de golpe si el Sacs que dejaste es el mismo que hay hoy. No lo es."},{"id":"en2","tipo":"encabezado","nivel":2,"texto":"Axo, el asistente de IA"},{"id":"li3","tipo":"lista","items":["Le hablas por chat o de viva voz y **hace cosas**: da de alta un producto desde una foto, crea una orden de compra, mueve un apartado, saca un reporte, edita productos en lote.","Tiene **memoria de tu negocio**: aprende cómo trabajas y te lo recuerda. Cada mañana manda un boletín con lo que necesita atención.","Importa catálogos conversando: le pasas el Excel y él pregunta lo que le falta."]},{"id":"en4","tipo":"encabezado","nivel":2,"texto":"Inventario y abasto"},{"id":"li5","tipo":"lista","items":["**Nivelación entre sucursales con asistente**: el sistema calcula cada noche qué talla y qué color falta en cada tienda y te propone los traspasos; tú apruebas y ejecutas.","Mínimos y máximos automáticos por grupo, con tres fórmulas y protección de lo que fijas a mano.","Pedidos inteligentes al proveedor por tipo de producto, back-orders de punta a punta y tablero del conteo físico."]},{"id":"en6","tipo":"encabezado","nivel":2,"texto":"Ventas y punto de venta"},{"id":"li7","tipo":"lista","items":["**Punto de venta móvil con kit de conexión**: sigue vendiendo sin internet y sincroniza solo cuando vuelve.","Búsqueda avanzada por variante en el POS, cortesías y vales con comprobación, continuidad de efectivo entre turnos y corte neto de cancelaciones.","Mensajes de WhatsApp al cliente desde el sistema: apartado, pedido listo, cashback ganado."]},{"id":"en8","tipo":"encabezado","nivel":2,"texto":"Canales y comercio"},{"id":"li9","tipo":"lista","items":["**Integración con TikTok Shop**: pedidos, inventario y catálogo desde el mismo Sacs. Y la Pasarela Instantánea, que sube una prenda a TikTok Shop con foto y video hechos con IA en minutos.","Colecciones y widget de e-commerce con combos; torre de control para eventos y ventas en vivo."]},{"id":"en10","tipo":"encabezado","nivel":2,"texto":"Administración y dirección"},{"id":"li11","tipo":"lista","items":["Cuentas de efectivo y bancos, con la bandeja bancaria conectada a tu banco.","Reporte ejecutivo con pestaña financiera, tablero de metas y comisiones por tienda y por vendedor, y reportes programados que llegan solos al correo."]},{"id":"me12","tipo":"metricas","items":[{"cifra":"+1,000","texto":"mejoras publicadas"},{"cifra":"6 meses","texto":"de trabajo del equipo de producto"},{"cifra":"$0","texto":"de costo extra en tu año"}]},{"id":"te13","tipo":"texto","texto":"Todo esto está incluido en el año sin costo, porque el año es del plan más completo. En la reunión, Aarón te enseña en pantalla solo lo que aplica a ti."},{"id":"bo14","tipo":"boton","texto":"📅 Reservar mi reunión con Aarón","href":"https://www.sacscloud.com/agendar/director-general","align":"center","sub":"Verlo en una cuenta real, no en diapositivas · 30 minutos"}]'::jsonb, true);

insert into email_templates (nombre, asunto, preview_text, tipo, layout, categoria, bloques, activo)
values ('Año sin costo 5 · Implementado en siete días', 'Cómo dejamos Sacs operando en {{empresa|tu negocio}} en 7 días', 'El plan día por día. Nosotros cargamos, configuramos y capacitamos; tú apruebas.', 'automatizado', 'lienzo', 'relacion', '[{"tipo":"portada","imagen":"https://www.sacscloud.com/email/portadas/wb-siete-dias.jpg","alt":"","etiqueta":"La implementación","titulo":"Siete días, un plan por escrito, y lo hacemos nosotros","id":"po0"},{"id":"te1","tipo":"texto","texto":"Hola {{nombre|Hola}}. «Implementar» fue la palabra que más pesó la primera vez: un catálogo por cargar, reglas por definir, un equipo por capacitar, todo mientras la tienda sigue vendiendo. Ahora se hace distinto: con un plan de **siete días hábiles**, con una consultora asignada, y con nosotros haciendo el trabajo pesado."},{"id":"en2","tipo":"encabezado","nivel":2,"texto":"Día por día"},{"id":"li3","tipo":"lista","items":["**Día 1 · Entender.** Sesión de una hora con tu consultora: qué vendes, cuántas tiendas, de dónde sale tu inventario, qué reportes necesitas ver. Sale el plan por escrito con el punto de «listo».","**Día 2 · Tu catálogo, cargado por nosotros.** Nos pasas lo que tengas —Excel, Shopify, fotos, tu sistema anterior— y lo cargamos con tallas, colores, precios y costos. Si fuiste cliente, tus datos siguen ahí y se retoman.","**Día 3 · Reglas y precios.** Listas de precios, descuentos, apartados, mínimos y máximos, impuestos y tickets con tu logo. Contigo en pantalla, no en un formulario.","**Día 4 · Tiendas y equipo.** Sucursales, cajas, usuarios y permisos. Cada persona entra con lo que le toca ver y nada más.","**Día 5 · Capacitación en vivo.** Una sesión con tu equipo de piso sobre el punto de venta y otra contigo sobre inventario, reportes y Axo. Quedan grabadas para quien entre después.","**Día 6 · Vendiendo en paralelo.** Tu equipo vende en Sacs con nosotros al lado por WhatsApp. Lo que aparece, se corrige ese mismo día.","**Día 7 · Punto de listo.** Revisamos juntos la lista del día 1: catálogo cargado, equipo vendiendo, reportes saliendo. Si se cumple, lo firmamos. Si no, seguimos hasta que sí, sin costo."]},{"id":"me4","tipo":"metricas","items":[{"cifra":"7 días","texto":"hábiles, del plan al punto de listo"},{"cifra":"1 persona","texto":"asignada, con nombre y WhatsApp"},{"cifra":"0 horas","texto":"tuyas capturando catálogo"}]},{"id":"av5","tipo":"aviso","texto":"**Garantía de implementación.** Si al terminar el arranque tu operación no está corriendo de verdad, no seguimos y no te cuesta nada. Se pone por escrito antes de empezar."},{"id":"bo6","tipo":"boton","texto":"📅 Reservar mi reunión con Aarón","href":"https://www.sacscloud.com/agendar/director-general","align":"center","sub":"El día 1 se agenda en la reunión · es lo único que hace falta para empezar"},{"id":"te7","tipo":"texto","texto":"Si quieres ver el plan aplicado a tu caso antes de la reunión, contéstame con cuántas tiendas tienes hoy y de dónde sale tu catálogo, y te lo mando por escrito."}]'::jsonb, true);

insert into email_templates (nombre, asunto, preview_text, tipo, layout, categoria, bloques, activo)
values ('Año sin costo 6 · El año, en letra grande', 'El año sin costo, en letra grande: qué incluye y qué no pedimos', 'Doce meses del plan completo, sin tarjeta, con tus datos de vuelta y con salida libre.', 'automatizado', 'lienzo', 'relacion', '[{"tipo":"portada","imagen":"https://www.sacscloud.com/email/portadas/wb-ano.jpg","alt":"","etiqueta":"Los términos","titulo":"Doce meses. Todo incluido. Sin letra chiquita.","id":"po0"},{"id":"te1","tipo":"texto","texto":"Hola {{nombre|Hola}}. Cuando algo es gratis, la pregunta correcta es «¿dónde está la trampa?». Te la contesto como la contestaría Aarón en la reunión: con los términos completos, en letra grande."},{"id":"en2","tipo":"encabezado","nivel":2,"texto":"Qué incluye"},{"id":"li3","tipo":"lista","items":["**Doce meses del plan más completo de Sacs**, con todos los módulos: punto de venta, inventario, nivelación, e-commerce y TikTok Shop, bancos, reportes, Axo con IA. No una versión recortada.","**La implementación de siete días, hecha por nosotros**, con consultora asignada y garantía por escrito.","**Tus datos de vuelta.** Si fuiste cliente, tu catálogo, tus clientes y tu historial siguen guardados y se retoman donde los dejaste.","**Acompañamiento durante el año**, no solo al arrancar: revisiones periódicas con tu consultora y el aviso automático si la cuenta baja de actividad.","**Tu equipo y tus tiendas actuales**, sin cobrar por usuario ni por sucursal adicional dentro de tu operación de hoy."]},{"id":"en4","tipo":"encabezado","nivel":2,"texto":"Qué no pedimos"},{"id":"li5","tipo":"lista","items":["**No pedimos tarjeta ni anticipo.** El año se activa en la reunión, sin cobro.","**No pedimos permanencia.** Si a los tres meses no te sirve, te vas con tus datos, y esta vez sabremos por qué.","**No pedimos que renueves.** Al terminar el año decides con doce meses de datos en la mano, al precio de lista que esté vigente. Te lo decimos desde el primer día, no al final."]},{"id":"en6","tipo":"encabezado","nivel":2,"texto":"Por qué lo hacemos"},{"id":"te7","tipo":"texto","texto":"Porque te fallamos, y un descuento no arregla eso. Y porque nos conviene: un cliente que se fue y vuelve a quedarse nos enseña más que diez nuevos. Si el año sale bien, ganamos los dos; si no, habremos aprendido algo que ninguna encuesta nos iba a decir."},{"id":"ci8","tipo":"cita","texto":"Un año sin costo es caro para nosotros. Perder a un cliente por segunda vez sería mucho más caro.","autor":"Aarón Herzberg, director general de Sacs"},{"id":"bo9","tipo":"boton","texto":"📅 Reservar mi reunión con Aarón","href":"https://www.sacscloud.com/agendar/director-general","align":"center","sub":"Los términos se confirman por escrito en la minuta de la reunión"},{"id":"te10","tipo":"texto","texto":"Cualquier duda sobre los términos, contéstame este correo y te la respondo por escrito antes de la reunión."}]'::jsonb, true);

insert into email_templates (nombre, asunto, preview_text, tipo, layout, categoria, bloques, activo)
values ('Año sin costo 7 · Así se atiende hoy una cuenta', 'Así se atiende hoy una cuenta de Sacs, con nombres y horarios', 'Quién te contesta, en cuánto tiempo, y qué pasa cuando algo no avanza.', 'automatizado', 'lienzo', 'relacion', '[{"tipo":"portada","imagen":"https://www.sacscloud.com/email/portadas/wb-atencion.jpg","alt":"","etiqueta":"El servicio, en operación","titulo":"Quién te contesta, cuándo, y qué pasa si algo no avanza","id":"po0"},{"id":"te1","tipo":"texto","texto":"Hola {{nombre|Hola}}. Hace unos días te conté qué cambiamos en el servicio. Hoy quiero enseñarte cómo se ve eso en una semana normal de una cuenta activa, porque las promesas de servicio se parecen todas hasta que las miras de cerca."},{"id":"en2","tipo":"encabezado","nivel":2,"texto":"Tu equipo, con nombre"},{"id":"li3","tipo":"lista","items":["**Tu consultora asignada** —yo, o una compañera del equipo— es la primera persona que ves y la que sigue contigo. Tiene tu WhatsApp, conoce tu tienda y revisa tu cuenta cada semana aunque no le escribas.","**El equipo de atención** contesta el WhatsApp oficial de Sacs de lunes a viernes en horario de oficina, con respuesta en el día. Si es algo que detiene la venta, se atiende al momento.","**Axo, dentro del sistema**, resuelve a cualquier hora lo que antes era un ticket: «configura este descuento», «sácame las ventas por vendedor de la semana», «da de alta este producto con esta foto».","**Dirección.** Si algo no avanza en el tiempo acordado, se escala a Aarón y te responde él. No es una frase: es la misma reunión a la que te estamos invitando."]},{"id":"en4","tipo":"encabezado","nivel":2,"texto":"Lo que pasa sin que lo pidas"},{"id":"li5","tipo":"lista","items":["Después de cada sesión o llamada te llega una minuta con acuerdos, responsables y fechas.","Los compromisos con fecha se persiguen solos: si el nuestro se vence, salta una alerta del lado del equipo, no del tuyo.","Si tu cuenta baja de actividad, alguien te llama esa semana para entender qué pasa.","Cada mañana Axo te manda un boletín con lo que necesita atención en tu negocio: inventario, ventas, pendientes."]},{"id":"ci6","tipo":"cita","texto":"Lo que cambió no es que contestamos más rápido. Es que ya no esperamos a que preguntes.","autor":"Aarón Herzberg, director general de Sacs"},{"id":"bo7","tipo":"boton","texto":"📅 Reservar mi reunión con Aarón","href":"https://www.sacscloud.com/agendar/director-general","align":"center","sub":"En la reunión puedes pedir conocer a quien sería tu consultora"},{"id":"bo8","tipo":"boton","texto":"💬 O escríbeme por WhatsApp","href":"https://wa.me/525593027234?text=Hola%20Andrea%2C%20quiero%20que%20me%20llames%20antes%20de%20agendar%20con%20Aar%C3%B3n.","align":"center","sub":"Si prefieres que te llame yo primero","color":"#2AB5A0"}]'::jsonb, true);

insert into email_templates (nombre, asunto, preview_text, tipo, layout, categoria, bloques, activo)
values ('Año sin costo 8 · Vuelves donde lo dejaste', '{{empresa|Tu negocio}} sigue guardado en Sacs, tal como lo dejaste', 'Catálogo, clientes e historial intactos. Cómo se vería tu primer día de vuelta.', 'automatizado', 'lienzo', 'relacion', '[{"tipo":"portada","imagen":"https://www.sacscloud.com/email/portadas/wb-datos.jpg","alt":"","etiqueta":"Volver","titulo":"Vuelves donde lo dejaste, no desde cero","id":"po0"},{"id":"te1","tipo":"texto","texto":"Hola {{nombre|Hola}}. Una de las cosas que más frenan a quien piensa en volver es imaginar que hay que empezar otra vez. No es así. Tu cuenta no se borró: tu catálogo, tus clientes, tus ventas históricas y tu configuración siguen guardados."},{"id":"en2","tipo":"encabezado","nivel":2,"texto":"Cómo se vería tu primer día"},{"id":"li3","tipo":"lista","items":["Entras y **tu catálogo está ahí**, con tallas, colores y precios. Lo que cambió desde entonces se actualiza el día 2 del arranque, con nosotros.","**Tus clientes y su historial** de compras siguen completos: los apartados, los puntos, las devoluciones. Se retoman.","**Tus reportes históricos** siguen disponibles: puedes comparar este mes contra el mismo mes del año en que te fuiste.","Lo nuevo —Axo, la nivelación, el POS móvil, TikTok Shop— **se activa encima de lo que ya tenías**, no en lugar de."]},{"id":"en4","tipo":"encabezado","nivel":2,"texto":"Lo que hacen hoy negocios como el tuyo"},{"id":"te5","tipo":"texto","texto":"Marcas de ropa, calzado y accesorios con dos, cinco y veinte tiendas: venden en piso y en TikTok Shop desde el mismo inventario, mueven la talla que sobra en una tienda a la que la necesita antes de que se pierda la venta, y reciben cada mañana un boletín con lo que hay que atender. Nada de eso existía en el Sacs que dejaste."},{"id":"av6","tipo":"aviso","texto":"Si prefieres arrancar limpio, también se puede: se archiva lo anterior y se carga de nuevo. Se decide contigo el día 1."},{"id":"bo7","tipo":"boton","texto":"📅 Reservar mi reunión con Aarón","href":"https://www.sacscloud.com/agendar/director-general","align":"center","sub":"Tu cuenta se retoma en la misma reunión"},{"id":"te8","tipo":"texto","texto":"Si quieres, antes de la reunión te mando un resumen de lo que hay guardado en tu cuenta: productos, clientes y último movimiento. Contéstame «resumen» y te lo preparo."}]'::jsonb, true);

insert into email_templates (nombre, asunto, preview_text, tipo, layout, categoria, bloques, activo)
values ('Año sin costo 9 · Las siete preguntas', 'Las siete preguntas que nos han hecho sobre el año sin costo', '¿De verdad gratis? ¿Qué pasa al terminar? ¿Tengo que hablar con el director? Contestadas.', 'automatizado', 'lienzo', 'relacion', '[{"tipo":"portada","imagen":"https://www.sacscloud.com/email/portadas/wb-preguntas.jpg","alt":"","etiqueta":"Preguntas","titulo":"Lo que nos han preguntado sobre el año sin costo","id":"po0"},{"id":"te1","tipo":"texto","texto":"Hola {{nombre|Hola}}. Varios de los clientes que ya tuvieron su reunión con Aarón llegaron con las mismas dudas. Te las dejo contestadas, por si son las tuyas."},{"id":"li2","tipo":"lista","items":["**¿De verdad es gratis, sin tarjeta?** Sí. Se activa en la reunión, sin cobro y sin datos de pago. Lo autoriza el director en persona.","**¿Qué pasa al terminar el año?** Decides tú, con doce meses de datos. Si sigues, el precio es el de lista vigente en ese momento, y lo conoces desde el primer día. Si no, te llevas tus datos.","**¿Y si no me convence a los dos meses?** Te vas. No hay permanencia ni penalización. Solo te pedimos que nos digas por qué.","**¿Tengo que hablar con el director? Prefiero que me llame alguien del equipo.** También se puede: contéstame este correo y te llamo yo. Pero la activación del año la hace Aarón, porque es él quien la autoriza.","**¿Cuánto tiempo me va a quitar la implementación?** La sesión del día 1 (una hora), dos capacitaciones (una hora cada una) y aprobar lo que cargamos. Lo demás lo hacemos nosotros.","**¿Aplica si ahora uso otro sistema?** Sí. Cargamos desde lo que tengas y, si quieres, corremos los dos en paralelo la primera semana.","**¿Hasta cuándo puedo tomar la reunión?** El espacio en la agenda de Aarón está abierto esta temporada para los clientes que se fueron. No te pongo una fecha límite inventada; te digo que cuando se cierre, dejo de escribir."]},{"id":"bo3","tipo":"boton","texto":"📅 Reservar mi reunión con Aarón","href":"https://www.sacscloud.com/agendar/director-general","align":"center","sub":"30 minutos · sin costo · la activación se hace en la misma llamada"},{"id":"te4","tipo":"texto","texto":"Si tu pregunta no está aquí, contéstame este correo y te la respondo por escrito."}]'::jsonb, true);

insert into email_templates (nombre, asunto, preview_text, tipo, layout, categoria, bloques, activo)
values ('Año sin costo 10 · La puerta queda abierta', 'Último correo: la reunión con Aarón queda abierta', 'No te vuelvo a escribir por esto. La liga sigue funcionando y la propuesta sigue en pie.', 'automatizado', 'lienzo', 'relacion', '[{"tipo":"portada","imagen":"https://www.sacscloud.com/email/portadas/wb-puerta.jpg","alt":"","etiqueta":"Último correo","titulo":"Aquí le paro. La puerta queda abierta.","id":"po0"},{"id":"te1","tipo":"texto","texto":"Hola {{nombre|Hola}}. Este es el último correo de esta serie. Te escribí diez veces en un mes sobre una sola cosa —un año de Sacs sin costo, dicho por el director— y si no contestaste, lo entiendo: quizá el momento no es este, quizá ya resolviste con otra herramienta, o quizá la razón por la que te fuiste sigue pesando más que cualquier propuesta. Las tres son válidas."},{"id":"en2","tipo":"encabezado","nivel":2,"texto":"Lo que queda en pie"},{"id":"li3","tipo":"lista","items":["La reunión con Aarón Herzberg sigue disponible en la misma liga, sin fecha de caducidad esta temporada.","El año sin costo, con implementación en siete días y garantía por escrito, se activa en esa reunión.","Tus datos siguen guardados en tu cuenta.","Yo sigo del otro lado de este correo y del WhatsApp de Sacs, para cuando quieras."]},{"id":"ci4","tipo":"cita","texto":"Gracias por haber confiado en Sacs una vez. Si nos das una segunda, esta vez no te vamos a dejar solo.","autor":"Aarón Herzberg, director general de Sacs"},{"id":"bo5","tipo":"boton","texto":"📅 Reservar mi reunión con Aarón","href":"https://www.sacscloud.com/agendar/director-general","align":"center","sub":"La liga sigue activa aunque este sea el último correo"},{"id":"te6","tipo":"texto","texto":"Si prefieres que no te escribamos más, abajo puedes cancelar la suscripción y se respeta al momento. Que te vaya muy bien."}]'::jsonb, true);

-- 3) Los pasos.
insert into crm_secuencia_pasos (secuencia_id, orden, dia, canal, email_template_id, activo)
select '11111111-2222-4333-8444-5555555555c1', v.orden, v.dia, 'correo', t.id, true
from (values
  (20, 1, 'Año sin costo 1 · Un año sin costo, dicho por el director'),
  (40, 3, 'Año sin costo 2 · Qué pasa en esos 30 minutos'),
  (60, 6, 'Año sin costo 3 · La razón por la que te fuiste ya no existe'),
  (80, 9, 'Año sin costo 4 · Más de mil mejoras en seis meses'),
  (100, 12, 'Año sin costo 5 · Implementado en siete días'),
  (120, 16, 'Año sin costo 6 · El año, en letra grande'),
  (140, 20, 'Año sin costo 7 · Así se atiende hoy una cuenta'),
  (160, 24, 'Año sin costo 8 · Vuelves donde lo dejaste'),
  (180, 28, 'Año sin costo 9 · Las siete preguntas'),
  (200, 32, 'Año sin costo 10 · La puerta queda abierta')
) as v(orden, dia, plantilla)
join email_templates t on t.nombre = v.plantilla;

